(window.__quranSurahs=window.__quranSurahs||{})[51]={"nomPhon":"Adh-Dhaariyat","versets":{"1":{"text":"Par les vents qui éparpillent!","arabe":"وَٱلذَّٰرِيَٰتِ ذَرْوًۭا"},"2":{"text":"Par les porteurs de fardeaux!","arabe":"فَٱلْحَٰمِلَٰتِ وِقْرًۭا"},"3":{"text":"Par les glisseurs agiles!","arabe":"فَٱلْجَٰرِيَٰتِ يُسْرًۭا"},"4":{"text":"Par les distributeurs selon un commandement!","arabe":"فَٱلْمُقَسِّمَٰتِ أَمْرًا"},"5":{"text":"Ce qui vous est promis est certainement vrai.","arabe":"إِنَّمَا تُوعَدُونَ لَصَادِقٌۭ"},"6":{"text":"Et la Rétribution arrivera inévitablement.","arabe":"وَإِنَّ ٱلدِّينَ لَوَٰقِعٌۭ"},"7":{"text":"Par le ciel aux voies parfaitement tracées!","arabe":"وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ"},"8":{"text":"vous divergez sur ce que vous dites.","arabe":"إِنَّكُمْ لَفِى قَوْلٍۢ مُّخْتَلِفٍۢ"},"9":{"text":"Est détourné de lui quiconque a été détourné de la foi.","arabe":"يُؤْفَكُ عَنْهُ مَنْ أُفِكَ"},"10":{"text":"Maudits soient les menteurs,","arabe":"قُتِلَ ٱلْخَرَّٰصُونَ"},"11":{"text":"qui sont plongés dans l'insouciance.","arabe":"ٱلَّذِينَ هُمْ فِى غَمْرَةٍۢ سَاهُونَ"},"12":{"text":"Ils demandent: «A quand le jour de la Rétribution?»","arabe":"يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ"},"13":{"text":"Le jour où ils seront éprouvés au Feu:","arabe":"يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ"},"14":{"text":"«Goûtez à votre épreuve [punition]; voici ce que vous cherchiez à hâter».","arabe":"ذُوقُوا۟ فِتْنَتَكُمْ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ"},"15":{"text":"Les pieux seront dans des Jardins et [parmi] des sources,","arabe":"إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ"},"16":{"text":"recevant ce que leur Seigneur leur aura donné. Car ils ont été auparavant des bienfaisants:","arabe":"ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ"},"17":{"text":"ils dormaient peu, la nuit,","arabe":"كَانُوا۟ قَلِيلًۭا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ"},"18":{"text":"et aux dernières heures de la nuit ils imploraient le pardon [d'Allah];","arabe":"وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ"},"19":{"text":"et dans leurs biens, il y avait un droit au mendiant et au déshérité.","arabe":"وَفِىٓ أَمْوَٰلِهِمْ حَقٌّۭ لِّلسَّآئِلِ وَٱلْمَحْرُومِ"},"20":{"text":"Il y a sur terre des preuves pour ceux qui croient avec certitude;","arabe":"وَفِى ٱلْأَرْضِ ءَايَٰتٌۭ لِّلْمُوقِنِينَ"},"21":{"text":"ainsi qu'en vous-mêmes. N'observez-vous donc pas?","arabe":"وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ"},"22":{"text":"Et il y a dans le ciel votre subsistance et ce qui vous a été promis.","arabe":"وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ"},"23":{"text":"Par le Seigneur du ciel et de la terre! Ceci est tout aussi vrai que le fait que vous parliez.","arabe":"فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّۭ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ"},"24":{"text":"T'est-il parvenu le récit des visiteurs honorables d'Abraham?","arabe":"هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ"},"25":{"text":"Quand ils entrèrent chez lui et dirent: «Paix!», il [leur] dit: «Paix, visiteurs inconnus».","arabe":"إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ قَوْمٌۭ مُّنكَرُونَ"},"26":{"text":"Puis il alla discrètement à sa famille et apporta un veau gras.","arabe":"فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍۢ سَمِينٍۢ"},"27":{"text":"Ensuite il l'approcha d'eux... «Ne mangez-vous pas?» dit-il.","arabe":"فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ"},"28":{"text":"Il ressentit alors de la peur vis-à-vis d'eux. Ils dirent: «N'aie pas peur». Et ils lui annoncèrent [la naissance] d'un garçon plein de savoir.","arabe":"فَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍۢ"},"29":{"text":"Alors sa femme s'avança en criant, se frappa le visage et dit: «Une vieille femme stérile...»","arabe":"فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍۢ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌۭ"},"30":{"text":"Ils dirent: «Ainsi a dit ton Seigneur. C'est Lui vraiment le Sage, l'Omniscient».","arabe":"قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ ۖ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ"},"31":{"text":"Alors [Abraham] dit: «Quelle est donc votre mission, ô envoyés?»","arabe":"۞ قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ"},"32":{"text":"Ils dirent: «Nous avons été envoyés vers des gens criminels,","arabe":"قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ"},"33":{"text":"pour lancer sur eux des pierres de glaise,","arabe":"لِنُرْسِلَ عَلَيْهِمْ حِجَارَةًۭ مِّن طِينٍۢ"},"34":{"text":"marquées auprès de ton Seigneur à l'intention des outranciers».","arabe":"مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ"},"35":{"text":"Nous en fîmes sortir alors ce qu'il y avait comme croyants,","arabe":"فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ"},"36":{"text":"mais Nous n'y trouvâmes qu'une seule maison de gens soumis.","arabe":"فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍۢ مِّنَ ٱلْمُسْلِمِينَ"},"37":{"text":"Et Nous y laissâmes un signe pour ceux qui redoutent le douloureux châtiment;","arabe":"وَتَرَكْنَا فِيهَآ ءَايَةًۭ لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ"},"38":{"text":"[Il y a même un signe] en Moïse quand Nous l'envoyâmes, avec une preuve évidente, vers Pharaon.","arabe":"وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍۢ مُّبِينٍۢ"},"39":{"text":"Mais [celui-ci] se détourna confiant en sa puissance, et dit: «C'est un magicien ou un possédé!»","arabe":"فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌۭ"},"40":{"text":"Nous le saisîmes ainsi que ses troupes, puis les jetâmes dans les flots, pour son comportement blâmable.","arabe":"فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌۭ"},"41":{"text":"De même pour les 'Aad, quand Nous envoyâmes contre eux le vent dévastateur","arabe":"وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ"},"42":{"text":"n'épargnant rien sur son passage sans le réduire en poussière.","arabe":"مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ"},"43":{"text":"De même pour les Thamûd, quand il leur fut dit: «Jouissez jusqu'à un certain temps!»","arabe":"وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍۢ"},"44":{"text":"Ils défièrent le commandement de leur Seigneur. La foudre les saisit alors qu'ils regardaient.","arabe":"فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ"},"45":{"text":"Ils ne purent ni se mettre debout ni être secourus.","arabe":"فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍۢ وَمَا كَانُوا۟ مُنتَصِرِينَ"},"46":{"text":"De même, pour le peuple de Noé auparavant. Ils étaient des gens pervers.","arabe":"وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ"},"47":{"text":"Le ciel, Nous l'avons construit par Notre puissance: et Nous l'étendons [constamment] dans l'immensité.","arabe":"وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍۢ وَإِنَّا لَمُوسِعُونَ"},"48":{"text":"Et la terre, Nous l'avons étendue. Et de quelle excellente façon Nous l'avons nivelée!","arabe":"وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ"},"49":{"text":"Et de toute chose Nous avons créé [deux éléments] de couple. Peut-être vous rappellerez-vous?","arabe":"وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ"},"50":{"text":"«Fuyez donc vers Allah. Moi, je suis pour vous de Sa part, un avertisseur explicite.","arabe":"فَفِرُّوٓا۟ إِلَى ٱللَّهِ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ"},"51":{"text":"Ne placez pas avec Allah une autre divinité. Je suis pour vous de Sa part, un avertisseur explicite».","arabe":"وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ"},"52":{"text":"Ainsi, aucun Messager n'est venu à leurs prédécesseurs sans qu'ils n'aient dit: «C'est un magicien ou un possédé!»","arabe":"كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ"},"53":{"text":"Est-ce qu'ils se sont transmis cette injonction? Ils sont plutôt des gens transgresseurs.","arabe":"أَتَوَاصَوْا۟ بِهِۦ ۚ بَلْ هُمْ قَوْمٌۭ طَاغُونَ"},"54":{"text":"Détourne-toi d'eux, tu ne seras pas blâmé [à leur sujet].","arabe":"فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍۢ"},"55":{"text":"Et rappelle; car le rappel profite aux croyants.","arabe":"وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ"},"56":{"text":"Je n'ai créé les djinns et les hommes que pour qu'ils M'adorent.","arabe":"وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ"},"57":{"text":"Je ne cherche pas d'eux une subsistance; et Je ne veux pas qu'ils me nourrissent.","arabe":"مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ"},"58":{"text":"En vérité, c'est Allah qui est le Grand Pourvoyeur, Le Détenteur de la force, l'Inébranlable.","arabe":"إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ"},"59":{"text":"Ceux qui ont été injustes auront une part [de tourments] pareille à celle de leurs compagnons. Qu'ils ne soient pas trop pressés.","arabe":"فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًۭا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ"},"60":{"text":"Malheur donc à ceux qui ont mécru à cause du jour dont ils sont menacés!","arabe":"فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ"}}};